import{_ as o,F as l,W as p,X as d,Y as r,Z as t,$ as i,a1 as n}from"./framework-af1ddc77.js";const s={},h={id:"軍訓替代課程——拓展營",tabindex:"-1"},u={href:"https://thubook.help/thubook/%E4%B8%93%E9%A2%98/junxun.html",target:"_blank",rel:"noopener noreferrer"},f={id:"入學定級考試",tabindex:"-1"},b={href:"https://thubook.help/thubook/%E4%B8%93%E9%A2%98/yyfj.html",target:"_blank",rel:"noopener noreferrer"};function x(k,e){const a=l("ExternalLinkIcon");return p(),d("div",null,[e[7]||(e[7]=r("h1",{id:"台灣新生專區-更新中",tabindex:"-1"},[r("a",{class:"header-anchor",href:"#台灣新生專區-更新中","aria-hidden":"true"},"#"),t(" 台灣新生專區（更新中）")],-1)),e[8]||(e[8]=r("p",null,"由於台生的特殊性，本欄目旨在對本站中的某些條目進行補充或修正以保證符合台生的需求。",-1)),r("h2",h,[e[1]||(e[1]=r("a",{class:"header-anchor",href:"#軍訓替代課程——拓展營","aria-hidden":"true"},"#",-1)),e[2]||(e[2]=t()),r("a",u,[e[0]||(e[0]=t("軍訓",-1)),i(a)]),e[3]||(e[3]=t("替代課程——拓展營",-1))]),e[9]||(e[9]=n("<p>相對於大陸及港澳學生2+2學分的軍訓，台灣學生可以選擇參加**台灣新生拓展營**（3學分）來替代軍訓。</p><blockquote><p>⚠️ 因為軍訓中的「軍事理論」課程台灣學生是不能參與的，所以還是建議參加拓展營。</p></blockquote><p>拓展營主要事務有</p><ul><li><p>思想課程：各種（水）課，有的會需要做ppt。</p></li><li><p>太極拳：在輪滑場學習楊氏太極拳，結訓的時候需要能完整打出全套拳法。雖然你會覺得很莫名其妙，但至少你不是跟軍訓的同學一起曬太陽，再加上這門課是記P/F的，放輕鬆就行。</p></li><li><p>晨跑：周二周四早上七點集合慢跑3000米，注意不要熬夜~~和吃巧樂茲配雪碧~~。</p></li><li><p>成材報告：含金量極低。相信我，由於此活動是綁在軍訓下的，所以你可以不去。</p></li><li><p>宿舍內務檢查：雖然原則上不會查你，但是為了不波及室友最好還是整理一下。</p></li><li><p>拉練（可選）：你可以在大半夜穿奇裝異服跟著軍訓同學繞圓明園兩圈，這會是你獨一無二的回憶。</p></li><li><p>閱讀報告：在第二周以ppt形式作一本書的讀書報告，非常輕鬆。</p></li><li><p>消防演習：大概早上八點二十會有人在你宿舍門口丟煙霧彈，有序撤離即可。（注意，在大陸的火災逃生是宣揚拿濕毛巾摀住口鼻的）</p></li><li><p>實踐活動：參觀博物館、植物園、圖書館。</p></li></ul><p>雖然拓展營活動密度不如軍訓，但還是建議保持作息。</p>",5)),r("h2",f,[e[5]||(e[5]=r("a",{class:"header-anchor",href:"#入學定級考試","aria-hidden":"true"},"#",-1)),e[6]||(e[6]=t()),r("a",b,[e[4]||(e[4]=t("入學定級考試",-1)),i(a)])]),e[10]||(e[10]=n('<h3 id="英文定級考" tabindex="-1"><a class="header-anchor" href="#英文定級考" aria-hidden="true">#</a> 英文定級考</h3><p>雖然作為台灣學生你會覺得你的英文非常好，但是依據學長姊的說法能夠達到四級的基本上在台生中只有1\\~2人。為了確保你不會爽吃3級戴上痛苦面具，沒有把握的建議還是保二級。</p><h3 id="數學定級考" tabindex="-1"><a class="header-anchor" href="#數學定級考" aria-hidden="true">#</a> 數學定級考</h3><p>範圍超出台灣課綱，不過此成績不影響你之後的選課。</p><h3 id="物理定級考" tabindex="-1"><a class="header-anchor" href="#物理定級考" aria-hidden="true">#</a> 物理定級考</h3><p>範圍超出台灣課綱，不過此成績不影響你之後的選課。</p><h3 id="計算機摸底考試" tabindex="-1"><a class="header-anchor" href="#計算機摸底考試" aria-hidden="true">#</a> 計算機摸底考試</h3><p>水木書院2026搞出的紙質考試，不過並沒有叫你手搓代碼，其提供了相當多的提示。此成績不影響你之後的選課。</p>',8))])}const E=o(s,[["render",x],["__file","ec09661eb52d.html.vue"]]);export{E as default};
